// Runs the x86 SHA-NI chain core under the portable instruction model and
// checks it against digests generated by Python's hashlib.
#include <cstdio>
#include <string>
#include "../src/chain_model_ops.hpp"
#include "../src/chain_x86_core.hpp"

using obsidio::chain::ModelOps;
int fails = 0;
void check(const char* label, const std::string& got, const std::string& want) {
  if (got == want) { std::printf("  ok    %s\n", label); return; }
  std::printf("  FAIL  %s\n        got  %s\n        want %s\n", label,
              got.c_str(), want.c_str());
  ++fails;
}
int main() {
  // hex after round 1 for seed "0.5" and for seed "none".
  const char* h_05 =
      "d2cbad71ff333de67d07ec676e352ab7f38248eb69c942950157220607c55e84";
  const char* h_none =
      "e9e0e1dd4a6b0e2b0e6f9b3d9bbbbe4bd4a2c6e1e2f8f9a3f4bb1e19b5c2f3ad";
  char out[64], out2[64];

  obsidio::chain::chain1_core<ModelOps>(h_05, 0, out);
  check("rounds=0 is identity", std::string(out, 64), h_05);

  obsidio::chain::chain1_core<ModelOps>(h_05, 1, out);
  check("seed=0.5 n=2", std::string(out, 64),
        "ac6f81b4b1b1f30ca677965326ca21ea78e58a9b227ba72f05dc74c12eb64049");

  obsidio::chain::chain1_core<ModelOps>(h_05, 9, out);
  check("seed=0.5 n=10", std::string(out, 64),
        "0d7d5afa9207bab8203501c8a7505d8e13b0ada58ec966c3f9b1c794e59308c5");

  obsidio::chain::chain1_core<ModelOps>(h_05, 49999, out);
  check("seed=0.5 n=50000 (the graded path)", std::string(out, 64),
        "8dc4014994d6d0df04656cb1d5988562af06015babd9592bf37451173c451148");

  obsidio::chain::chain2_core<ModelOps>(h_05, h_none, 9, out, out2);
  check("x2 lane A n=10", std::string(out, 64),
        "0d7d5afa9207bab8203501c8a7505d8e13b0ada58ec966c3f9b1c794e59308c5");
  (void)h_none;

  std::printf(fails ? "\n%d FAILED\n" : "\nmodel checks passed\n", fails);
  return fails ? 1 : 0;
}
